    else stage0 <= 1'h0;
  always_ff @(posedge async_ff_clk, posedge async_ff_rst)
    if (async_ff_rst) stage1 <= 1'h1;
    else stage1 <= stage0;
  assign usb_rst = async_ff_rst;
  assign audio_clk = async_ff_clk;
  assign r_rst = stage1;
endmodule
